
# Build.ps1

$ErrorActionPreference = 'Stop'

$projectRoot = $PSScriptRoot
$classPath = Join-Path $projectRoot 'Rosetta/Classes'
$outputPath = Join-Path $projectRoot 'Rosetta/Rosetta.psm1'

# Class files in dependency order
$classFiles = @(
    'RosettaPeopleSearchBy.ps1'
    'RosettaJobTypeID.ps1'
    'RosettaDepartment.ps1'
    'RosettaEmployeeAssociation.ps1'
    'RosettaStudentAssociation.ps1'
    'RosettaPerson.ps1'
    'RosettaAPIWorker.ps1'
)

$moduleContent = @"
# Rosetta PowerShell Module
# AUTO-GENERATED - DO NOT EDIT
# Generated by Build.ps1

"@

foreach ($file in $classFiles) {
    $filePath = Join-Path $classPath $file

    if (-not (Test-Path $filePath)) {
        throw "Class file not found: $filePath"
    }

    Write-Host "Adding class: $file"

    $content = Get-Content -Path $filePath -Raw

    $moduleContent += @"

# ----------------------------------------
# Source: $file
# ----------------------------------------

$content

"@
}

# Write the combined module
Set-Content -Path $outputPath `
    -Value $moduleContent `
    -Encoding utf8

Write-Host "Module generated: $outputPath"
